import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse(`{"title":"Admin Hub — Glacier","description":"A tour of Glacier's settings hub — tabs, live preview, presets, import/export and factory reset.","frontmatter":{"title":"Admin Hub — Glacier","description":"A tour of Glacier's settings hub — tabs, live preview, presets, import/export and factory reset."},"headers":[],"relativePath":"glacier/user-guide/admin-hub.md","filePath":"glacier/user-guide/admin-hub.md","lastUpdated":null}`),o={name:"glacier/user-guide/admin-hub.md"};function s(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="the-admin-hub" tabindex="-1">The Admin Hub <a class="header-anchor" href="#the-admin-hub" aria-label="Permalink to &quot;The Admin Hub&quot;">​</a></h1><p>Everything Glacier does is configured from <strong>Admin → Extensions → Glacier</strong> — no files to edit, no CLI. The hub groups its 120+ settings into tabs and previews every change live before you save.</p><h2 id="tabs-at-a-glance" tabindex="-1">Tabs at a glance <a class="header-anchor" href="#tabs-at-a-glance" aria-label="Permalink to &quot;Tabs at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>What lives there</th></tr></thead><tbody><tr><td><strong>Appearance</strong></td><td>Dark/light/auto mode, radius, both color palettes, mode toggle, footer, favicon, theme-color, watermark</td></tr><tr><td><strong>Background</strong></td><td>Page background (none / 16 patterns / image), auth-page background, login card alignment</td></tr><tr><td><strong>Sidebar</strong></td><td>Dock, rail style, tab effects, hover style, brand block, server block, server switcher</td></tr><tr><td><strong>Console</strong></td><td>Stats style, graph mode, zones layout editor, command input, terminal color</td></tr><tr><td><strong>Animations</strong></td><td>Master motion, page reveals, file animations, console reveal</td></tr><tr><td><strong>Files</strong></td><td>File manager glass, row tint, icon style and colors</td></tr><tr><td><strong>Dashboard</strong></td><td>Server card style and layout, fallback cover image, welcome bar</td></tr><tr><td><strong>Topbar</strong></td><td>Utility bar, search pill, clock and date formats</td></tr><tr><td><strong>Announcements</strong></td><td>Multi-entry markdown announcements + the dismissable banner with CTA</td></tr><tr><td><strong>Tabs</strong></td><td>Visual tab manager (see <a href="./../tabs">Tabs</a>)</td></tr><tr><td><strong>Glass</strong></td><td>Sidebar and container opacity/blur</td></tr><tr><td><strong>Advanced</strong></td><td>Shortcuts, import/export, factory reset</td></tr></tbody></table><p>Every key, type and default is in the <a href="./../../configuration/reference">Configuration Reference</a>.</p><h2 id="live-preview" tabindex="-1">Live preview <a class="header-anchor" href="#live-preview" aria-label="Permalink to &quot;Live preview&quot;">​</a></h2><p>The hub renders the theme behind the settings as you edit: palette changes, patterns, radius and glass apply to the page you&#39;re looking at before you press <strong>Save</strong>. What you see is literally what your users get — there is no &quot;save and pray&quot; step.</p><h2 id="presets-and-the-seed-generator" tabindex="-1">Presets and the seed generator <a class="header-anchor" href="#presets-and-the-seed-generator" aria-label="Permalink to &quot;Presets and the seed generator&quot;">​</a></h2><p>Two fast paths to a coherent look:</p><ul><li><strong>Curated presets</strong> — one click fills both dark and light palettes from a designed set.</li><li><strong>Seed-color generator</strong> — pick one brand color; Glacier derives a balanced full palette (both modes) around it, including readable text and hairline steps.</li></ul><div class="tip custom-block"><p class="custom-block-title">Preset first, then tune</p><p>Presets overwrite the palette fields only — your sidebar, console and layout choices are untouched. Starting from a preset and nudging <code>accent</code> is the intended workflow.</p></div><h2 id="import-export-factory-reset" tabindex="-1">Import / export / factory reset <a class="header-anchor" href="#import-export-factory-reset" aria-label="Permalink to &quot;Import / export / factory reset&quot;">​</a></h2><p>On the <strong>Advanced</strong> tab:</p><ul><li><strong>Export</strong> downloads the entire configuration as one JSON file — every tab, list and toggle.</li><li><strong>Import</strong> applies such a file back (validated against the same rules as the form, so a corrupt file fails cleanly instead of half-applying).</li><li><strong>Factory reset</strong> returns every key to its documented default. This is instant and affects all users; export first if in doubt.</li></ul><h2 id="announcements-vs-the-banner" tabindex="-1">Announcements vs. the banner <a class="header-anchor" href="#announcements-vs-the-banner" aria-label="Permalink to &quot;Announcements vs. the banner&quot;">​</a></h2><p>Two independent systems live on the Announcements tab:</p><ul><li><strong>Announcements list</strong> (<code>announcements</code>) — multiple rich entries with markdown bodies for the dashboard; good for news, maintenance notices, changelogs.</li><li><strong>The banner</strong> (<code>announcement_*</code>) — one dismissable, tone-colored strip with an optional CTA button; good for a single important callout.</li></ul><h2 id="validation-behavior" tabindex="-1">Validation behavior <a class="header-anchor" href="#validation-behavior" aria-label="Permalink to &quot;Validation behavior&quot;">​</a></h2><p>Every field validates on save against the rules in the reference (ranges, hex format, URL shape, JSON validity for lists). A failing field is flagged inline and <strong>nothing is written</strong> — saves are all-or-nothing per form, so you can never strand the panel in a half-saved theme.</p>',19)])])}const p=t(o,[["render",s]]);export{u as __pageData,p as default};
